import{z as m,x as n,o as i,c as E,q as t,j as o,D as r,d as l,s as h,S as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"点扩散函数与 Airy 斑","description":"","frontmatter":{"title":"点扩散函数与 Airy 斑","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/psf-airy.md","filePath":"litho/psf-airy.md","lastUpdated":1791413859000}'),s={name:"litho/psf-airy.md"};function p(B,a,d,_,c,f){const e=n("Mermaid");return i(),E("div",null,[a[2]||(a[2]=t('<h1 id="点扩散函数与-airy-斑" tabindex="-1">点扩散函数与 Airy 斑 <a class="header-anchor" href="#点扩散函数与-airy-斑" aria-label="Permalink to &quot;点扩散函数与 Airy 斑&quot;">​</a></h1><div class="epigraph"><p>圆孔光瞳的傅里叶逆变换是艾里斑；有限口径的全部糊边，先是这个核与物体的卷积，不是胶把边咬圆了。</p><footer>—— Airy 圆孔衍射；Fourier 光学表述见 Goodman；显微镜两针孔读法见 Born &amp; Wolf</footer></div><p><a href="/litho/sampling-theorem-imaging">上一课</a>把带限像放到了 Nyquist 网格上。缺口是：<strong>连续核还没有名字</strong>——频域的光瞳乘 \\(T\\)，空域就是点扩散与物卷积。本课钉 PSF 与圆孔的 Airy 斑。传递函数如何从核变出来，留给<a href="/litho/ctf-otf">下一课</a>。不要把艾里第一暗环半径改写成产线 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>傅里叶对已经说 \\(\\mathrm{circ}\\leftrightarrow\\mathrm{jinc}\\)。计算与计量仍常问：一个接触孔、一条孤立线，空中像的「光学直径」有多大。答案是振幅点扩散 \\(h=\\mathcal{F}^{-1}\\{P\\}\\)（相干）或强度点扩散 \\(|h|^2\\)（非相干）。圆孔无像差时，\\(|h|^2\\) 就是 Airy 斑：中心亮斑加一圈圈暗环。</p><p>缺口不是再证一次卷积定理，而是把这只核钉成后课二维图形的尺度：线端变圆、角被切、孔比线难，首先是因为核有宽度，其次才是胶与刻蚀。</p><h3 id="相干核与非相干核" tabindex="-1">相干核与非相干核 <a class="header-anchor" href="#相干核与非相干核" aria-label="Permalink to &quot;相干核与非相干核&quot;">​</a></h3><p>相干：\\(U=t*h\\)，\\(h\\propto\\mathcal{F}^{-1}\\{P\\}\\)。非相干：\\(I=I_\\mathrm{obj}*|h|^2\\)。部分相干没有单只 PSF，但每个源点仍用同一只 \\(h\\)，只是物频谱相对光瞳平移。<a href="/litho/hopkins-tcc">Hopkins</a> 把这些切片收成 TCC，本课不重写重叠积分。</p><p><span class="marginnote">Airy 斑的第一暗环约在 \\(0.61\\,\\lambda/\\mathrm{NA}\\)（非相干强度、圆孔、空气）。这是显微镜里两斑刚可分辨的几何，见 Born &amp; Wolf。光刻产线式子带 \\(k_1\\)，见<a href="/litho/rayleigh-litho">瑞利课</a>，本课不把 0.61 叫成 \\(k_1\\)。</span></p><p><span class="marginnote">直觉类比：PSF 像「点一个点后墨水在纸上洇开的形状」。无论你写多细的字，纸上每个笔画都是这团墨迹的叠印——字糊不糊由墨迹形状决定，不是笔的错。光学里这团「墨迹」就是点扩散函数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>理想圆瞳、无遮拦、无像差：</p> \\[h(r)\\propto \\frac{J_1(2\\pi r\\,\\mathrm{NA}/\\lambda)}{r},\\qquad \\mathrm{PSF}_\\mathrm{inc}(r)=|h(r)|^2. \\]<p>\\(J_1\\) 的第一零点给出暗环。有中心遮拦（某些 EUV 光瞳）或切趾，零点移动、旁瓣升高，仍叫点扩散，只是不再是教科书 Airy。离焦与像差进 \\(P\\) 的相位，\\(h\\) 变胖、旁瓣变形——机制在<a href="/litho/defocus-as-aberration">离焦作为像差</a>，本课只承认核会变。</p><p>光学直径：核的有效宽度几个 \\(\\lambda/\\mathrm{NA}\\)。OPC 邻域、SRAF 是否印出、孤立孔的能量从哪来，都按这个直径截断，而不是按设计规则的「最小间距」截断。</p><p><span class="marginnote">数字实例：取 \\(\\lambda=193\\) nm、\\(\\mathrm{NA}=1.35\\)，Airy 第一暗环约 \\(0.61\\times193/1.35\\approx 87\\) nm——这就是「光学直径」的量级：比许多设计规则的最小线宽还宽，所以邻近效应要按几个 \\(\\lambda/\\mathrm{NA}\\) 算，不能只看版图间距。</span></p>',16)),(i(),o(A,null,{default:r(()=>[h(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%85%89%E7%9E%B3%20P%22%5D%20--%3E%20H%5B%22h%20%3D%20F%E2%81%BB%C2%B9(P)%22%5D%0A%20%20H%20--%3E%20COH%5B%22%E7%9B%B8%E5%B9%B2%3A%20t%20*%20h%22%5D%0A%20%20H%20--%3E%20INC%5B%22%E9%9D%9E%E7%9B%B8%E5%B9%B2%3A%20Iobj%20*%20%7Ch%7C%C2%B2%22%5D%0A%20%20COH%20--%3E%20AIR%5B%22%E5%9C%86%E5%AD%94%20%E2%86%92%20Airy%22%5D%0A%20%20INC%20--%3E%20AIR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="落到上一课的网格" tabindex="-1">落到上一课的网格 <a class="header-anchor" href="#落到上一课的网格" aria-label="Permalink to &quot;落到上一课的网格&quot;">​</a></h3><p>连续 Airy 在强度 Nyquist 上采样，旁瓣才不折叠。网格按节点名去取「每纳米一点」而不看 \\(\\mathrm{NA}/\\lambda\\)，会既浪费又可能仍采不足旁瓣。本课的核是连续对象；离散是上一课的接口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>点物的谱是平的，光瞳切出一块圆，逆变换必是 jinc。扩展物等于许多点物的叠加：相干时场相加（干涉），非相干时强度相加。这就是「糊」的线性图像。<a href="/litho/abbe-imaging">阿贝</a>用频谱语言说同一件事：通带外的高频回不来，空域就是核把锐边打斜。</p>',4)),(i(),o(A,null,{default:r(()=>[h(e,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E4%B8%80%E4%B8%AA%E7%82%B9%E7%89%A9%22%5D%20--%3E%20SP%5B%22%E7%82%B9%E7%89%A9%E9%A2%91%E8%B0%B1%E6%98%AF%E5%B9%B3%E7%9A%84%22%5D%0A%20%20SP%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%E5%88%87%E5%87%BA%E5%9C%86%E5%BD%A2%E4%B8%80%E5%9D%97%22%5D%0A%20%20PUP%20--%3E%20JINC%5B%22%E9%80%86%E5%8F%98%E6%8D%A2%20%3D%20jinc%20%2F%20Airy%20%E6%A0%B8%22%5D%0A%20%20OBJ%5B%22%E6%89%A9%E5%B1%95%E7%89%A9%22%5D%20--%3E%20SUM%5B%22%E8%AE%B8%E5%A4%9A%E7%82%B9%E7%89%A9%E5%83%8F%E7%9A%84%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20SUM%20--%3E%20COH%5B%22%E7%9B%B8%E5%B9%B2%3A%20%E5%9C%BA%E7%9B%B8%E5%8A%A0%20%E4%BC%9A%E5%B9%B2%E6%B6%89%22%5D%0A%20%20SUM%20--%3E%20INCOH%5B%22%E9%9D%9E%E7%9B%B8%E5%B9%B2%3A%20%E5%BC%BA%E5%BA%A6%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20COH%20--%3E%20IMG%5B%22%E5%83%8F%20%3D%20%E7%89%A9%E4%B8%8E%E6%A0%B8%E7%9A%84%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20INCOH%20--%3E%20IMG%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>两个邻近孔的像是两只核的重叠。重叠多少，下一课用传递函数读，再下一课用 Sparrow / Rayleigh 两种判据读。本课只提供单只核。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到「光学糊了多少」，默认先问 \\(h\\) 或 \\(|h|^2\\) 的宽度，再问胶扩散。圆孔无像差时可以叫 Airy；有遮拦或 SMO 光瞳时叫「该光瞳的 PSF」，不要硬贴艾里暗环公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>标量圆孔 Airy 不含偏振、不含薄膜。高 \\(\\mathrm{NA}\\) 矢量沉积会让「有效核」随偏振与焦深变，定义仍是点物的像，数值不再是 \\(J_1\\)。也不要把 Strehl 比（有像差时峰值下降）在本课展开；那是核的峰值归一，见主干 Strehl 课。禁止用未公开的镜头「实测 Airy」表替代 jinc。</p><p><span class="marginnote">常见误区：把 Airy 暗环的 0.61 直接当成产线的 \\(k_1\\)。0.61 是显微镜里「两斑刚好分得开」的几何判据；产线 \\(\\mathrm{CD}=k_1\\lambda/\\mathrm{NA}\\) 的 \\(k_1\\) 是照明、胶与工艺一起凑出来的经验数，两者不是同一个东西。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PSF 是光瞳的逆变换；圆孔给出 Airy（jinc / \\(J_1\\)）。</li><li>相干卷积场，非相干卷积强度；部分相干按源切片用同一 \\(h\\)。</li><li>光学直径几个 \\(\\lambda/\\mathrm{NA}\\)，是后课二维邻近的尺度。</li><li>0.61 是显微镜暗环几何，不是产线 \\(k_1\\)。</li><li>下一课：核的傅里叶伙伴——CTF / OTF。</li><li>出处：Airy；Goodman；Born &amp; Wolf。</li></ul>',8))])}const b=m(s,[["render",p]]);export{u as __pageData,b as default};
